edits.new:
// Beberapa kunci sitasi dapat menunjuk karya yang sama; daftar pustaka menampilkan satu entri per karya.
const unique = [...new Set([...used].map((key) => refs[key]))]
	.sort((a, b) => a.runs.map((r) => r.text).join('').localeCompare(b.runs.map((r) => r.text).join(''), 'en'));
const entries = unique.map((r) => r.runs);
return {
	title, author: meta.author, affiliation: meta.affiliation, email: meta.email, date,
	abstractId, keywordsId: keywordsId.join(', '), abstractEn, keywordsEn: keywordsEn.join(', '),
	blocks: B, refRuns: entries, refLinks: unique.map((r) => r.link),
	references: entries.map((e) => e.map((r) => r.text).join('')),
	highlights: keyPts, appendix: APP,
};
